head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > applyFormat]<br/>Column 에서 입력값을 편집할때 Column 에 적용된 표시 포맷을 유지할지 설정합니다.",
    "validation" : [
        "Column 의 표시 포맷은 displayFormat, displayFormatter 등으로 설정합니다.",
        "display 설정 시, 입력이 완료된 후 포커스가 해제되면 Column 의 표시 포맷이 적용됩니다.",
        "미설정 시, 입력이 완료된 후 포커스가 해제되면 Column 의 표시 포맷이 적용됩니다.",
        "display 설정 시, Column 에서 값을 입력할 때마다 표시 포맷이 다시 적용됩니다.",
        "all 설정 시, 입력값을 편집하는 중에도 Column 의 표시 포맷을 적용합니다.",
        "Column 의 inputType 속성값이 'text', 'textImage', 'secret', 'calendar', 'spinner' 인 경우만 동작합니다.",
        "바인딩된 DataList 엔 포맷이 제거된 실제 입력값이 저장됩니다.",
        "편집 상태가 아닌 Column 은 applyFormat 설정값과 관계없이 표시 포맷이 항상 적용됩니다.",
        "inputType='calendar' 인 Column 은 displayFormat 속성을 설정하지 않으면 ioFormat 속성이 표시 포맷으로 적용됩니다.",
    ]
}



scwin.gVar = {
    // 편집 중 키를 뗄 때마다 기록한 입력창 값 (셀 더블클릭 시 초기화)
    "editValue" : []
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_applyFormat.setValue("all");
    con_inputType.setValue("text");
    con_format.setValue("displayFormat");
    con_calDisplayFormat.setValue("yyyy/MM/dd");
    scwin.con_inputType_onviewchange();

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// displayFormatter 로 지정하는 표시 포맷 함수 (천 단위 구분 + 원 단위 표시)
scwin.formatter_won = function (value) {
    if (value === "" || value === null || typeof value === "undefined") {
        return value;
    }
    return WebSquare.text.formatCurrency(String(value), "#,###") + " 원";
}



// inputType 에 맞는 조건만 활성화
//  - calendar : 표시 포맷(숫자) 비활성, calendar displayFormat 활성
//  - 그 외    : 표시 포맷(숫자) 활성, calendar displayFormat 비활성
scwin.con_inputType_onviewchange = function () {
    let isCalendar = (con_inputType.getValue() === "calendar");
    con_format.setDisabled(isCalendar);
    con_calDisplayFormat.setDisabled(!isCalendar);
}



// 표시 포맷 설정 문자열 / 출력 문구 (inputType 별 조건 기준)
//  - calendar : ioFormat=yyyyMMdd 고정, displayFormat 은 con_calDisplayFormat (미설정 시 속성 없음)
//  - 그 외    : dataType=number + con_format (displayFormat #,### / displayFormatter)
scwin.getFormatAttr = function () {
    if (con_inputType.getValue() === "calendar") {
        let cCalDisplayFormat = con_calDisplayFormat.getValue();
        return ' ioFormat="yyyyMMdd"' + (cCalDisplayFormat === '' ? '' : ' displayFormat="' + cCalDisplayFormat + '"');
    }
    if (con_format.getValue() === "displayFormatter") {
        return ' dataType="number" displayFormatter="scwin.formatter_won"';
    }
    return ' dataType="number" displayFormat="#,###"';
}

scwin.getFormatText = function () {
    if (con_inputType.getValue() === "calendar") {
        let cCalDisplayFormat = con_calDisplayFormat.getValue();
        return "ioFormat=yyyyMMdd / displayFormat=" + (cCalDisplayFormat === '' ? "(미설정)" : cCalDisplayFormat);
    }
    if (con_format.getValue() === "displayFormatter") {
        return "displayFormatter=scwin.formatter_won";
    }
    return "displayFormat=#,###";
}



// comp 생성
//  - guide : 입력 방법 안내 Column (readOnly)
//  - val   : 검증 대상 Column (inputType 별 표시 포맷, applyFormat / inputType 을 옵션값으로 설정)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }
    scwin.gVar.editValue = [];

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cApplyFormat = con_applyFormat.getValue();
    let cInputType = con_inputType.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] calendar 는 ioFormat=yyyyMMdd, 그 외는 dataType=number\n[절차] 결과창 clear -> val 셀 더블클릭 (spinner 는 이어서 입력창 클릭) -> 입력 방법의 숫자를 한 자씩 입력 (calendar 는 달력 선택 없이 키 입력) -> 셀 밖 클릭으로 포커스 해제 -> 셀 값 확인\n[확인] 편집 중 입력창 값과 포커스 해제 후 셀 표시값 / getCellData 비교"', '', 'label1');

    // dataList 생성 (body column id 와 동일한 컬럼 id 사용)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="guide" name="guide" dataType="text"></w2:column>';
    strDlt += '<w2:column id="val" name="val" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "guide" : "숫자 입력 : " + (cInputType === "calendar" ? "20250115" : "12345"), "val" : "" }
    ], false);

    // val Column 속성
    let attrVal = ' inputType="' + cInputType + '"' + scwin.getFormatAttr();
    if (cInputType === "textImage") {
        // textImage 는 셀에 이미지도 표시되도록 아이콘 이미지 설정 (column_P_allowChar_1 과 동일 경로)
        attrVal += ' viewType="icon" imageSrc="/cm/images/base/ico_grid_del.svg"';
    }
    if (cApplyFormat !== '') {
        attrVal += ' applyFormat="' + cApplyFormat + '"';
    }

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:560px;height:80px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="300" style="" inputType="text" id="column1" value="입력 방법"></w2:column>';
    strTarget += '<w2:column width="240" style="" inputType="text" id="column2" value="val (' + cInputType + ')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="300" style="" inputType="text" id="guide" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="240" style="" id="val" value=""' + attrVal + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 편집 입력창 값 기록
    //  - spinner 는 oneditkeyup 이 발생하지 않으므로 GridView 영역의 keyup 으로 기록한다.
    //  - 셀 더블클릭(편집 진입) 시 기록 초기화
    target1.render.addEventListener("dblclick", function () {
        scwin.gVar.editValue = [];
    }, true);
    target1.render.addEventListener("keyup", scwin.recordEditValue, true);
}



// 편집 중 키를 뗄 때마다 입력창 값을 기록 (입력창의 포맷 처리가 끝난 뒤의 값을 읽는다)
scwin.recordEditValue = function (e) {
    let elem = e.target;
    if (!elem || elem.tagName !== "INPUT") {
        return;
    }
    setTimeout(function () {
        let arr = scwin.gVar.editValue;
        if (arr.length === 0 || arr[arr.length - 1] !== elem.value) {
            arr.push(elem.value);
        }
    }, 0);
}



// 설정값과 편집 중 입력창 값 / 포커스 해제 후 셀 표시값 / DataList 저장값 출력
//  - validation 2, 3, 4, 5 : 편집 중 입력창 값(키 입력마다) -> 포커스 해제 후 셀 표시값
//  - validation 1 : 표시 포맷(displayFormat / displayFormatter) 별 셀 표시값
//  - validation 6 : inputType 별 결과
//  - validation 7 : getCellData
//  - validation 8 : 포커스 해제 후(편집 상태 아님) 셀 표시값
//  - validation 9 : calendar + displayFormat 미설정 시 셀 표시값이 ioFormat(yyyyMMdd) 형식인지
scwin.btn_checkCell_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let cApplyFormat = con_applyFormat.getValue();

    bottom.setReturnValue("applyFormat : " + (cApplyFormat === '' ? "(미설정)" : cApplyFormat)
        + " / inputType : " + con_inputType.getValue() + " / " + scwin.getFormatText());

    let cellData = target1.getCellData(0, "val");
    let td = document.querySelector("td[id*='target1_cell_0_1']");
    let cellText = td ? td.textContent : "";

    // 편집하지 않았으면 값 줄은 출력하지 않는다
    if (scwin.gVar.editValue.length === 0 && (cellData === "" || cellData === null)) {
        return;
    }

    bottom.setReturnValue("편집 중 입력창 값 : " + scwin.gVar.editValue.join(" > ")
        + " -> 포커스 해제 후 셀 표시값 : " + cellText + " / getCellData : " + cellData);
}
